const INDEX = new Map(ETHER_MATS.map((d) => [d.id, d]));

/**
 * Récupère la définition d'un matériau d'Éther par son identifiant unique.
 * @param {string} [id] 
 * @returns {EtherMatDef}
 */
export function getEtherDef(id) {
  return (id && INDEX.get(id)) || ETHER_MATS[0];
}

/**
 * Génère ou récupère l'instance physique du matériau Three.js.
 * @param {string} [id] 
 * @returns {object} QcMat (MeshStandardMaterial ou équivalent)
 */
export function getEtherMat(id) {
  const d = getEtherDef(id);
  if (d.e && (d.i ?? 0) > 0) {
    return matLib.lit(d.color, d.e, d.i ?? 1, d.r);
  }
  if (d.cat === 'glass') {
    return matLib.physicalGlass(d.color, 1, Math.max(0.02, d.r));
  }
  if (d.t || (d.o ?? 1) < 1) {
    return matLib.glass(d.color, d.o ?? 0.4, d.r, d.m);
  }
  return matLib.hex(d.color, d.r, d.m);
}

/**
 * Liste les matériaux associés à une catégorie spécifique.
 * @param {EtherCat} cat 
 * @returns {EtherMatDef[]}
 */
export function getEtherByCat(cat) {
  return ETHER_MATS.filter((d) => d.cat === cat);
}

/**
 * Recherche textuelle floue sur les noms, identifiants ou catégories.
 * @param {string} query 
 * @returns {EtherMatDef[]}
 */
export function searchEtherMats(query) {
  const q = String(query || '').toLowerCase().trim();
  if (!q) return [...ETHER_MATS];
  return ETHER_MATS.filter(
    (d) => d.name.toLowerCase().includes(q) || d.id.includes(q) || d.cat.includes(q)
  );
}

export const ETHER_MAT_STATS = Object.freeze({
  total: ETHER_MATS.length,
  cats:  Object.freeze([...new Set(ETHER_MATS.map((d) => d.cat))]),
});

export { SIG };
export default ETHER_MATS;